//! Code-metrics gate for the MuduDB workspace.
//!
//! Walks `crates/**/*.rs` and enforces two classes of limit described in
//! `code_metrics.toml`:
//!
//! * a maximum number of physical lines per source file, and
//! * a maximum number of physical lines per item (class / struct / function).
//!
//! Files whose header carries the canonical `Generated by ... Do not edit
//! manually.` marker are treated as generated and skipped, and `exclude`
//! entries skip additional files or directory prefixes.

#![deny(clippy::unwrap_used)]
#![deny(clippy::expect_used)]
#![deny(clippy::dbg_macro)]

use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use clap::Parser;
use serde::Deserialize;
use syn::spanned::Spanned;
use syn::visit::Visit;

/// Default maximum physical lines in a single source file.
const DEFAULT_MAX_FILE_LINES: usize = 2000;

/// Default maximum physical lines in a single item.
const DEFAULT_MAX_ITEM_LINES: usize = 200;

/// Command-line interface for the metrics gate.
#[derive(Debug, Parser)]
#[command(
    name = "mudu_metrics",
    about = "Enforce code-metrics limits over crates/**/*.rs"
)]
struct Cli {
    /// Directory to scan for `.rs` files.
    #[arg(long, default_value = ".")]
    root: PathBuf,

    /// Path to the metrics config file. Defaults to `<root>/code_metrics.toml`
    /// when present, otherwise built-in defaults are used.
    #[arg(long)]
    config: Option<PathBuf>,
}

/// Metrics limits read from `code_metrics.toml`.
#[derive(Debug, Deserialize)]
struct Config {
    #[serde(default = "default_max_file_lines")]
    max_file_lines: usize,
    #[serde(default = "default_max_item_lines")]
    max_struct_lines: usize,
    #[serde(default = "default_max_item_lines")]
    max_function_lines: usize,
    #[serde(default = "default_max_item_lines")]
    max_class_lines: usize,
    #[serde(default)]
    exclude: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            max_file_lines: default_max_file_lines(),
            max_struct_lines: default_max_item_lines(),
            max_function_lines: default_max_item_lines(),
            max_class_lines: default_max_item_lines(),
            exclude: Vec::new(),
        }
    }
}

fn default_max_file_lines() -> usize {
    DEFAULT_MAX_FILE_LINES
}

fn default_max_item_lines() -> usize {
    DEFAULT_MAX_ITEM_LINES
}

/// A single metrics violation, reported as `path:line: message`.
struct Violation {
    path: PathBuf,
    line: usize,
    message: String,
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let config = load_config(&cli)?;

    let mut files = collect_files(&cli.root)?;
    files.sort();

    let mut violations = Vec::new();
    let mut checked = 0usize;
    let mut skipped_excluded = 0usize;
    let mut skipped_generated = 0usize;

    for path in files {
        let relative = path.strip_prefix(&cli.root).unwrap_or(&path);
        if is_excluded(relative, &config.exclude) {
            skipped_excluded += 1;
            continue;
        }

        let content = mudu_sys::fs::sync::sync_read_to_string(&path)
            .with_context(|| format!("read {}", path.display()))?;

        if is_generated(&content) {
            skipped_generated += 1;
            continue;
        }

        checked += 1;
        check_file(&path, &content, &config, &mut violations)?;
    }

    for violation in &violations {
        println!(
            "{}:{}: {}",
            violation.path.display(),
            violation.line,
            violation.message
        );
    }

    if !violations.is_empty() {
        eprintln!(
            "mudu_metrics: {} violation(s) across {} checked file(s)",
            violations.len(),
            checked
        );
        return Err(anyhow::anyhow!(
            "code-metrics limits exceeded ({} violation(s))",
            violations.len()
        ));
    }

    println!(
        "mudu_metrics: {} file(s) checked, {} excluded, {} generated skipped — clean",
        checked, skipped_excluded, skipped_generated
    );
    Ok(())
}

/// Loads the config from `--config` or `<root>/code_metrics.toml`, falling
/// back to built-in defaults when neither is available.
fn load_config(cli: &Cli) -> Result<Config> {
    if let Some(path) = &cli.config {
        let text = mudu_sys::fs::sync::sync_read_to_string(path)
            .with_context(|| format!("read config {}", path.display()))?;
        return toml::from_str(&text).with_context(|| format!("parse config {}", path.display()));
    }

    let candidate = cli.root.join("code_metrics.toml");
    if mudu_sys::fs::sync::sync_path_exists(&candidate) {
        let text = mudu_sys::fs::sync::sync_read_to_string(&candidate)
            .with_context(|| format!("read config {}", candidate.display()))?;
        return toml::from_str(&text)
            .with_context(|| format!("parse config {}", candidate.display()));
    }

    Ok(Config::default())
}

/// Recursively collects `.rs` files under `root`, skipping build artifacts and
/// hidden directories.
fn collect_files(root: &Path) -> Result<Vec<PathBuf>> {
    let mut files = Vec::new();
    walk_dir(root, &mut files)?;
    Ok(files)
}

fn walk_dir(dir: &Path, out: &mut Vec<PathBuf>) -> Result<()> {
    for entry in mudu_sys::fs::sync::sync_read_dir_entries(dir)
        .with_context(|| format!("read dir {}", dir.display()))?
    {
        let file_type = entry.file_type()?;
        if file_type.is_symlink() {
            continue;
        }
        if file_type.is_dir() {
            let name = entry.file_name();
            let name = name.to_str().unwrap_or("");
            if name == "target" || name.starts_with('.') {
                continue;
            }
            walk_dir(&entry.path(), out)?;
        } else if file_type.is_file()
            && entry.path().extension().and_then(|e| e.to_str()) == Some("rs")
        {
            out.push(entry.path());
        }
    }
    Ok(())
}

/// Returns whether `relative` matches any exclude pattern. Non-glob patterns
/// match as directory prefixes, so an entry like `crates/foo/bar` excludes
/// everything under it.
fn is_excluded(relative: &Path, exclude: &[String]) -> bool {
    let rel = relative.to_string_lossy();
    exclude.iter().any(|pattern| {
        let has_meta = pattern.chars().any(|c| matches!(c, '*' | '?' | '['));
        if has_meta {
            return glob::Pattern::new(pattern)
                .map(|p| p.matches(rel.as_ref()))
                .unwrap_or(false);
        }
        let prefix = format!("{pattern}/");
        rel.as_ref() == pattern.as_str() || rel.as_ref().starts_with(&prefix)
    })
}

/// Returns whether `content` carries the canonical generated-code marker in
/// its header.
fn is_generated(content: &str) -> bool {
    content
        .lines()
        .take(10)
        .any(|line| line.contains("Generated by") && line.contains("Do not edit manually."))
}

/// Checks the file-level limit and every class/struct/function item inside.
fn check_file(path: &Path, content: &str, config: &Config, out: &mut Vec<Violation>) -> Result<()> {
    let file_lines = content.lines().count();
    if file_lines > config.max_file_lines {
        out.push(Violation {
            path: path.to_path_buf(),
            line: 1,
            message: format!(
                "file is {file_lines} lines (limit {})",
                config.max_file_lines
            ),
        });
    }

    let file = syn::parse_file(content).with_context(|| format!("parse {}", path.display()))?;
    let mut visitor = ItemVisitor {
        config,
        path,
        violations: Vec::new(),
    };
    visitor.visit_file(&file);
    out.extend(visitor.violations);
    Ok(())
}

/// Visitor that records over-long classes, structs and functions, including
/// items nested inside modules, impl blocks and trait definitions.
struct ItemVisitor<'a> {
    config: &'a Config,
    path: &'a Path,
    violations: Vec<Violation>,
}

impl ItemVisitor<'_> {
    fn record(&mut self, span: proc_macro2::Span, kind: &str, max: usize, name: Option<&str>) {
        let start = span.start().line;
        let end = span.end().line;
        let lines = end.saturating_sub(start) + 1;
        if lines > max {
            let ident = name.map(|n| format!(" `{n}`")).unwrap_or_default();
            self.violations.push(Violation {
                path: self.path.to_path_buf(),
                line: start,
                message: format!("{kind}{ident} is {lines} lines (limit {max})"),
            });
        }
    }
}

impl<'ast> Visit<'ast> for ItemVisitor<'_> {
    fn visit_item(&mut self, item: &'ast syn::Item) {
        if let Some((kind, max, name)) = classify_item(item, self.config) {
            self.record(item.span(), kind, max, name.as_deref());
        }
        syn::visit::visit_item(self, item);
    }

    fn visit_impl_item(&mut self, item: &'ast syn::ImplItem) {
        if let syn::ImplItem::Fn(func) = item {
            self.record(
                item.span(),
                "function",
                self.config.max_function_lines,
                Some(&func.sig.ident.to_string()),
            );
        }
        syn::visit::visit_impl_item(self, item);
    }

    fn visit_trait_item(&mut self, item: &'ast syn::TraitItem) {
        if let syn::TraitItem::Fn(func) = item {
            self.record(
                item.span(),
                "function",
                self.config.max_function_lines,
                Some(&func.sig.ident.to_string()),
            );
        }
        syn::visit::visit_trait_item(self, item);
    }
}

/// Classifies a top-level (or module-nested) item into a metrics category.
fn classify_item(
    item: &syn::Item,
    config: &Config,
) -> Option<(&'static str, usize, Option<String>)> {
    match item {
        syn::Item::Fn(func) => Some((
            "function",
            config.max_function_lines,
            Some(func.sig.ident.to_string()),
        )),
        syn::Item::Struct(item_struct) => Some((
            "struct",
            config.max_struct_lines,
            Some(item_struct.ident.to_string()),
        )),
        syn::Item::Enum(item_enum) => Some((
            "struct",
            config.max_struct_lines,
            Some(item_enum.ident.to_string()),
        )),
        syn::Item::Union(item_union) => Some((
            "struct",
            config.max_struct_lines,
            Some(item_union.ident.to_string()),
        )),
        syn::Item::Impl(_) => Some(("class", config.max_class_lines, None)),
        syn::Item::Trait(item_trait) => Some((
            "class",
            config.max_class_lines,
            Some(item_trait.ident.to_string()),
        )),
        _ => None,
    }
}
